package cn.jiguang.cordova.push;
import android.os.Bundle;import android.os.Looper;import org.apache.cordova.CallbackContext;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.Shadows;import org.robolectric.annotation.Config;import org.robolectric.annotation.LooperMode;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35, manifest=Config.NONE) @LooperMode(LooperMode.Mode.PAUSED)
public class BridgeLifecycleTest {
 static class Reply extends CallbackContext {int calls;JSONObject result;String error;Reply(){super("test",null);}@Override public void success(){calls++;}@Override public void success(JSONObject value){calls++;result=value;}@Override public void error(String value){calls++;error=value;}}
 @Test public void separateAndDuplicateReplies() throws Exception {PendingCallbackRegistry r=new PendingCallbackRegistry();Reply a=new Reply(),b=new Reply();long x=r.add(a),y=r.add(b);JSONObject v=new JSONObject().put("code",7);r.success(y,v);r.success(x,null);r.error(y,"duplicate");Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,a.calls);assertEquals(1,b.calls);assertEquals(7,b.result.getInt("code"));}
 @Test public void resetDropsQueuedAndLateResults() {PendingCallbackRegistry r=new PendingCallbackRegistry();Reply a=new Reply();long x=r.add(a);r.success(x,null);r.clear();r.error(x,"late");Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(0,a.calls);assertFalse(r.contains(x));Reply b=new Reply();long y=r.add(b);assertTrue(y>x);r.success(y,null);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,b.calls);}
 @Test public void concurrentResultsKeepIdentity() throws Exception {PendingCallbackRegistry r=new PendingCallbackRegistry();Reply a=new Reply(),b=new Reply();long x=r.add(a),y=r.add(b);Thread one=new Thread(()->r.error(x,"a")),two=new Thread(()->r.error(y,"b"));one.start();two.start();one.join();two.join();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals("a",a.error);assertEquals("b",b.error);}
 @Test public void codecPreservesNestedValuesAndDropsNativeObjects() throws Exception {Bundle b=new Bundle();Bundle child=new Bundle();child.putBoolean("ok",true);child.putIntArray("ids",new int[]{1,2});b.putBundle("channels",child);b.putString("intent_private","hidden");b.putString("json","[1,true]");JSONObject o=SubscriptionResultCodec.fromBundle(b);assertTrue(o.getJSONObject("channels").getBoolean("ok"));assertEquals(2,o.getJSONObject("channels").getJSONArray("ids").getInt(1));assertEquals("[1,true]",o.getString("json"));assertFalse(o.has("intent_private"));}
 @Test public void codecStopsCyclicBundle() throws Exception {Bundle b=new Bundle();b.putBundle("self",b);JSONObject o=SubscriptionResultCodec.fromBundle(b);assertNotNull(o);}
}
